import re
s = '\`quick\` = implement→review · \`standard\` = design→implement→test→review→document · \`formal\` = spec→design→implement→test→coverage→review→document · \`coe\` = investigate→root-cause→fix→test→document · \`coverage\` = measure→test→verify.'
# split into space-separated tokens, then further split long arrow-chain tokens after each →
words = s.split(' ')
subtokens = []
for w in words:
    if '→' in w and len(w) > 20:
        parts = w.split('→')
        for i,p in enumerate(parts):
            if i < len(parts)-1:
                subtokens.append(p+'→')
            else:
                subtokens.append(p)
    else:
        subtokens.append(w)
print(subtokens)
width = 78
lines = []
cur = ''
for i,t in enumerate(subtokens):
    # decide whether to add space before t: no space if previous subtoken ends with → and came from same split chain
    sep = ' '
    if cur.endswith('→'):
        sep = ''
    cand = cur + sep + t if cur else t
    if len(cand) <= width:
        cur = cand
    else:
        lines.append(cur)
        cur = t
if cur:
    lines.append(cur)
for l in lines:
    print(len(l), l)
print('total', len(lines))
"

